//
//  AppPalette.swift
//  NYCFarmerMarkets
//
//  Single source of truth for every color in the app.
//  Change the values in `AppPalette.Base` and the whole app is recolored.
//  Views must only use the semantic tokens below (never literal colors).
//

import SwiftUI
#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

/// A color with a light and a dark appearance, stored as 0xRRGGBB so it can
/// also be used for contrast calculations.
nonisolated struct ColorToken: Sendable {
    let light: Int
    let dark: Int

    init(light: Int, dark: Int) {
        self.light = light
        self.dark = dark
    }

    /// Same color in both appearances.
    init(_ both: Int) {
        self.init(light: both, dark: both)
    }

    func hex(isDark: Bool) -> Int { isDark ? dark : light }

    #if canImport(UIKit)
    var platformColor: UIColor {
        let light = self.light, dark = self.dark
        return UIColor { traits in
            UIColor(hex: traits.userInterfaceStyle == .dark ? dark : light)
        }
    }
    var color: Color { Color(uiColor: platformColor) }
    #elseif canImport(AppKit)
    var platformColor: NSColor {
        let light = self.light, dark = self.dark
        return NSColor(name: nil) { appearance in
            let isDark = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
            return NSColor(hex: isDark ? dark : light)
        }
    }
    var color: Color { Color(nsColor: platformColor) }
    #endif
}

nonisolated enum AppPalette {

    // MARK: Base values (the ONLY place hex literals live)

    enum Base {
        static let primary = 0xC7D93D
        static let secondary = 0x98A62E
        static let deep = 0x525919
        static let highlight = 0xE6F28D
        static let surface = 0xF2F2F2
        /// Olive used as the app icon background.
        static let appIconOlive = 0x78872B
    }

    // MARK: Semantic tokens

    /// Screen background.
    static let background = ColorToken(light: Base.surface, dark: mix(Base.deep, 0x000000, 0.45))
    /// Row / card background.
    static let card = ColorToken(light: mix(Base.highlight, Base.surface, 0.55), dark: Base.deep)
    /// Selected row / callout background.
    static let cardSelected = ColorToken(light: Base.highlight, dark: mix(Base.deep, Base.primary, 0.25))
    /// Main text.
    static let textPrimary = ColorToken(light: Base.deep, dark: Base.surface)
    /// Secondary text.
    static let textSecondary = ColorToken(light: mix(Base.deep, Base.surface, 0.1), dark: Base.highlight)
    /// Tint for controls, links, selected tab, favorite icon.
    static let accent = ColorToken(light: Base.deep, dark: Base.primary)
    /// Filled shapes in the primary color (pins, buttons).
    static let accentFill = ColorToken(Base.primary)
    /// Content drawn on top of `accentFill`.
    static let onAccentFill = ColorToken(Base.deep)
    /// Decorative secondary color (borders, dividers, minor glyphs).
    static let accentSecondary = ColorToken(Base.secondary)
    /// Section header background.
    static let sectionHeader = ColorToken(light: Base.highlight, dark: mix(Base.deep, Base.secondary, 0.25))
    /// Hairlines and separators.
    static let separator = ColorToken(Base.secondary)
    /// App icon background.
    static let appIconBackground = ColorToken(Base.appIconOlive)

    // MARK: Helpers

    /// Linear blend of two 0xRRGGBB values. `amount` 0 = a, 1 = b.
    static func mix(_ a: Int, _ b: Int, _ amount: Double) -> Int {
        func channel(_ shift: Int) -> Int {
            let ca = Double((a >> shift) & 0xFF)
            let cb = Double((b >> shift) & 0xFF)
            return Int((ca + (cb - ca) * amount).rounded())
        }
        return (channel(16) << 16) | (channel(8) << 8) | channel(0)
    }

    /// WCAG relative luminance of a 0xRRGGBB value.
    static func luminance(_ hex: Int) -> Double {
        func linear(_ v: Int) -> Double {
            let c = Double(v) / 255
            return c <= 0.03928 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4)
        }
        return 0.2126 * linear((hex >> 16) & 0xFF)
            + 0.7152 * linear((hex >> 8) & 0xFF)
            + 0.0722 * linear(hex & 0xFF)
    }

    /// WCAG contrast ratio between two 0xRRGGBB values (1...21).
    static func contrast(_ a: Int, _ b: Int) -> Double {
        let la = luminance(a), lb = luminance(b)
        return (max(la, lb) + 0.05) / (min(la, lb) + 0.05)
    }
}

// MARK: - Platform color from hex

#if canImport(UIKit)
nonisolated extension UIColor {
    convenience init(hex: Int) {
        self.init(
            red: CGFloat((hex >> 16) & 0xFF) / 255,
            green: CGFloat((hex >> 8) & 0xFF) / 255,
            blue: CGFloat(hex & 0xFF) / 255,
            alpha: 1
        )
    }
}
#elseif canImport(AppKit)
nonisolated extension NSColor {
    convenience init(hex: Int) {
        self.init(
            srgbRed: CGFloat((hex >> 16) & 0xFF) / 255,
            green: CGFloat((hex >> 8) & 0xFF) / 255,
            blue: CGFloat(hex & 0xFF) / 255,
            alpha: 1
        )
    }
}
#endif

//
//  AppIcon.swift
//  NYCFarmerMarkets
//
//  Registry of every icon used in the UI. Swap an icon here and it changes
//  everywhere. Views must not use raw SF Symbol names.
//

import SwiftUI

nonisolated enum AppIcon: String, CaseIterable, Sendable {
    case tabMarkets
    case tabMap
    case tabFavorites
    case favoriteOn
    case favoriteOff
    case mapPin
    case ebt
    case yearRound
    case hours
    case location
    case district
    case cooking
    case year
    case close
    case openInMaps
    case offline
    case warning
    case emptySearch

    enum Source: Equatable, Sendable {
        case symbol(String)
        case asset(String)
    }

    var source: Source {
        switch self {
        case .tabMarkets: .asset("icon-pumpkin")
        case .tabMap: .symbol("moon.stars.fill")
        case .tabFavorites: .asset("icon-ghost-filled")
        case .favoriteOn: .asset("icon-ghost-filled")
        case .favoriteOff: .asset("icon-ghost-outline")
        case .mapPin: .asset("icon-bat")
        case .ebt: .symbol("sparkles")
        case .yearRound: .symbol("moon.fill")
        case .hours: .symbol("hourglass")
        case .location: .symbol("mappin.circle.fill")
        case .district: .symbol("eye.fill")
        case .cooking: .symbol("flame.fill")
        case .year: .symbol("calendar")
        case .close: .symbol("xmark.circle.fill")
        case .openInMaps: .symbol("map.fill")
        case .offline: .symbol("cloud.fog.fill")
        case .warning: .symbol("exclamationmark.triangle.fill")
        case .emptySearch: .symbol("eyes")
        }
    }

    /// Template image at its natural size (used by tab bars and labels).
    var image: Image {
        switch source {
        case .symbol(let name): Image(systemName: name)
        case .asset(let name): Image(name).renderingMode(.template)
        }
    }

    /// Plain-language name for accessibility.
    var accessibilityName: String {
        switch self {
        case .tabMarkets: "Markets"
        case .tabMap: "Map"
        case .tabFavorites: "Favorites"
        case .favoriteOn: "Favorite"
        case .favoriteOff: "Not a favorite"
        case .mapPin: "Market"
        case .ebt: "EBT"
        case .yearRound: "Open year round"
        case .hours: "Hours"
        case .location: "Address"
        case .district: "Community district"
        case .cooking: "Cooking permitted"
        case .year: "Year"
        case .close: "Close"
        case .openInMaps: "Go to Map"
        case .offline: "Offline"
        case .warning: "Warning"
        case .emptySearch: "No results"
        }
    }
}

/// Renders an `AppIcon` at a fixed point size, tinted by the foreground style.
struct IconView: View {
    let icon: AppIcon
    var size: CGFloat = 18

    init(_ icon: AppIcon, size: CGFloat = 18) {
        self.icon = icon
        self.size = size
    }

    var body: some View {
        Group {
            switch icon.source {
            case .symbol(let name):
                Image(systemName: name)
                    .font(.system(size: size))
            case .asset(let name):
                Image(name)
                    .renderingMode(.template)
                    .resizable()
                    .scaledToFit()
                    .frame(width: size, height: size)
            }
        }
        .accessibilityHidden(true)
    }
}

//
//  ThemeStyling.swift
//  NYCFarmerMarkets
//
//  Reusable styling built from AppPalette tokens, and global appearance.
//

import SwiftUI
#if canImport(UIKit)
import UIKit
#endif

extension View {
    /// Screen background using the theme.
    func themedBackground() -> some View {
        background(AppPalette.background.color.ignoresSafeArea())
    }

    /// Rounded card surface.
    func themedCard(selected: Bool = false) -> some View {
        padding(12)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .fill((selected ? AppPalette.cardSelected : AppPalette.card).color)
            )
            .overlay(
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .strokeBorder(AppPalette.separator.color.opacity(0.5), lineWidth: 1)
            )
    }
}

/// Filled button in the accent color.
struct ThemedButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .font(.headline)
            .foregroundStyle(AppPalette.onAccentFill.color)
            .padding(.horizontal, 16)
            .padding(.vertical, 10)
            .background(Capsule().fill(AppPalette.accentFill.color))
            .opacity(configuration.isPressed ? 0.7 : 1)
    }
}

enum ThemeAppearance {
    /// Applies the palette to bars. Call once at launch.
    static func apply() {
        #if canImport(UIKit) && !os(visionOS)
        let background = AppPalette.background.platformColor
        let text = AppPalette.textPrimary.platformColor
        let accent = AppPalette.accent.platformColor
        let muted = AppPalette.textSecondary.platformColor

        let nav = UINavigationBarAppearance()
        nav.configureWithOpaqueBackground()
        nav.backgroundColor = background
        nav.titleTextAttributes = [.foregroundColor: text]
        nav.largeTitleTextAttributes = [.foregroundColor: text]
        UINavigationBar.appearance().standardAppearance = nav
        UINavigationBar.appearance().scrollEdgeAppearance = nav
        UINavigationBar.appearance().tintColor = accent

        let tab = UITabBarAppearance()
        tab.configureWithOpaqueBackground()
        tab.backgroundColor = background
        for item in [tab.stackedLayoutAppearance, tab.inlineLayoutAppearance, tab.compactInlineLayoutAppearance] {
            item.selected.iconColor = accent
            item.selected.titleTextAttributes = [.foregroundColor: accent]
            item.normal.iconColor = muted
            item.normal.titleTextAttributes = [.foregroundColor: muted]
        }
        UITabBar.appearance().standardAppearance = tab
        UITabBar.appearance().scrollEdgeAppearance = tab
        #endif
    }
}

//
//  Market.swift
//  NYCFarmerMarkets
//

import Foundation
import CoreLocation

/// A farmers market from the NYC Open Data "NYC Farmers Markets" dataset (8vwk-6iz2).
nonisolated struct Market: Identifiable, Codable, Hashable, Sendable {
    let id: String
    let name: String
    let borough: String
    let address: String
    let year: String?
    let communityDistrict: String?
    let latitude: Double?
    let longitude: Double?
    let daysOfOperation: String?
    let hoursOfOperation: String?
    let acceptsEBT: String?
    let openYearRound: String?
    let healthDeptCooking: String?

    static let unknownBorough = "Unknown"

    var coordinate: CLLocationCoordinate2D? {
        guard let latitude, let longitude else { return nil }
        return CLLocationCoordinate2D(latitude: latitude, longitude: longitude)
    }

    // MARK: Raw API record

    /// One row exactly as returned by the API (every value is a string).
    struct Raw: Decodable, Sendable {
        let year: String?
        let marketname: String?
        let borough: String?
        let streetaddress: String?
        let community_district: String?
        let latitude: String?
        let longitude: String?
        let daysoperation: String?
        let hoursoperations: String?
        let accepts_ebt: String?
        let open_year_round: String?
        let nyc_dept_of_health_cooking: String?
    }

    /// Builds a market from a raw row. Returns nil when there is no name.
    init?(raw: Raw) {
        guard let name = Market.clean(raw.marketname) else { return nil }
        let address = Market.clean(raw.streetaddress) ?? ""
        self.name = name
        self.address = address
        self.id = Market.makeID(name: name, address: address)
        self.borough = Market.normalizeBorough(raw.borough)
        self.year = Market.clean(raw.year)
        self.communityDistrict = Market.clean(raw.community_district)
        self.latitude = Market.parseCoordinate(raw.latitude)
        self.longitude = Market.parseCoordinate(raw.longitude)
        self.daysOfOperation = Market.clean(raw.daysoperation)
        self.hoursOfOperation = Market.clean(raw.hoursoperations)
        self.acceptsEBT = Market.clean(raw.accepts_ebt)?.capitalizedFirst
        self.openYearRound = Market.clean(raw.open_year_round)?.capitalizedFirst
        self.healthDeptCooking = Market.clean(raw.nyc_dept_of_health_cooking)?.capitalizedFirst
    }

    // MARK: Helpers

    static func makeID(name: String, address: String) -> String {
        "\(name.lowercased())|\(address.lowercased())"
    }

    static func normalizeBorough(_ value: String?) -> String {
        guard let cleaned = clean(value) else { return unknownBorough }
        // Canonicalize capitalization ("brooklyn" -> "Brooklyn").
        let known = ["Manhattan", "Brooklyn", "Queens", "Bronx", "Staten Island"]
        if let match = known.first(where: { $0.caseInsensitiveCompare(cleaned) == .orderedSame }) {
            return match
        }
        return cleaned
    }

    static func clean(_ value: String?) -> String? {
        guard let trimmed = value?.trimmingCharacters(in: .whitespacesAndNewlines), !trimmed.isEmpty else {
            return nil
        }
        return trimmed
    }

    static func parseCoordinate(_ value: String?) -> Double? {
        guard let text = clean(value), let number = Double(text), number != 0 else { return nil }
        return number
    }
}

private extension String {
    /// "yes" -> "Yes"; leaves the rest of the string untouched.
    nonisolated var capitalizedFirst: String {
        prefix(1).uppercased() + dropFirst()
    }
}

